scwin.fn_get_isurcode = function() {
    //elw발행사
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_ElwInst.Reset();

    //etn발행사
    dts_EtnInst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_EtnInst.Reset();

    //dts_LpMbrNo.DataID = "/CodeAction.do?method=listLeadCom&For=R"; 
    //dts_LpMbrNo.Reset(); 
    scwin.fn_get_ElwLpMbrNo_cd(); // 현재 상장관련있는 LP
    scwin.fn_get_ElwInstLpMbrNo_cd(); // 발행사 및 현재 상장관련있는 LP
    scwin.fn_get_EtnInstLpMbrNo_cd(); // ETN발행사 및 현재 상장관련 있는 LP
    scwin.fn_get_EtfTrstCom3_cd(); // etf 현재 상장관련있는운용사
    scwin.fn_get_EtfTrstComLP3_cd(); // etf 운용사/LP 모두
    scwin.fn_get_PfTrstCom4_cd(); // pf 현재 상장관련있는운용사
    scwin.fn_get_PfTrstComLP4_cd(); // pf 운용사/LP 모두

    //CopyDataSet( dts_ElwInst , dts_ElwInst2) ;
    //cmb_ISUR_CD2.index =0;

    //CopyDataSet( dts_ElwInst , dts_ElwInst3) ;
    //cmb_ISUR_CD3.index =0;
    $c.stf.CopyDataSet(dts_LpMbrNo, dts_LpMbrNo2);
    $c.stf.CopyDataSet(dts_LpMbrNo, dts_LpMbrNo3);
    $c.stf.CopyDataSet(dts_LpMbrNo, dts_LpMbrNo4);
    cmb_ISUR_CD.setSelectedIndex(0);
    cmb_ISUR_CD2.setSelectedIndex(0);
    cmb_ISUR_CD3.setSelectedIndex(0);
    cmb_ISUR_CD4.setSelectedIndex(0);
};
