scwin.img_Regist_onclick = function() {
    if (rdo_ISUR_CD.getValue() == "0") {
        $c.win.alert("발행사 나 LP 항목을 선택하십시요.");
        rdo_ISUR_CD.focus();
        return true;
    }
    if (cmb_ISUR_CD.getSelectedIndex() == 0) {
        $c.win.alert("발행사 나 LP 회사를 선택하십시요.");
        cmb_ISUR_CD.focus();
        return true;
    }
    // 기 저장된 회사가 있는지 체크
    if (dts.getRowPosition() != 0) {
        $c.win.alert("이미 저장된 회사입니다.");
        //cmb_ISUR_CD.focus();
        return true;
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame();
};
