scwin.grd_OnDblClick = function(row, colid) {
    scwin.click_BYCORP_CHRG_BZ_TP_CD = dts.getCellData(row, 'BYCORP_CHRG_BZ_TP_CD');
    scwin.click_INVSTCOM_BZ_TP_CD = dts.getCellData(row, 'INVSTCOM_BZ_TP_CD');
    scwin.click_ISUR_CD = dts.getCellData(row, 'ISUR_CD');
    scwin.click_COM_ABBRV = dts.getCellData(row, 'COM_ABBRV');
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame();
};
