scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd2);
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd3);
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd4);
    rdo_ISUR_CD.setValue("0");
    rdo_ISUR_CD2.setValue("0");
    rdo_ISUR_CD3.setValue("0");
    rdo_ISUR_CD4.setValue("0");
    scwin.fn_get_isurcode();
    img_Elwlist.setSelectedTabIndex(1);
};
